local H=dofile('tests/lua/support/potion_basic_five_fixture.lua')
local n=0
local function test(name,fn)fn();n=n+1;print('PASS graph assertions '..name)end
local function rejects(a,b)
 local ok=pcall(H.same,a,b);assert(not ok,'unequal graph was accepted')
end
test('rejects splitting one shared table into two equal tables',function()
 local shared={value=1};rejects({first=shared,second=shared},{first={value=1},second={value=1}})
end)
test('rejects merging two distinct tables into one shared table',function()
 local shared={value=1};rejects({first={value=1},second={value=1}},{first=shared,second=shared})
end)
test('accepts equal private shared DAGs and self or mutual cycles',function()
 local leaf={value=1};local dag={a=leaf,b=leaf};local child={owner=dag};dag.child=child;dag.self=dag
 local copied=H.C.copy(dag);assert(copied~=dag and copied.a==copied.b and copied.self==copied and copied.child.owner==copied)
 H.same(dag,copied)
 local long={flag=false};for _=1,16 do long={a=long,b=long}end;H.same(long,H.C.copy(long))
end)
test('rejects different cycle topology and changed cyclic leaf values',function()
 local a={value=1};a.self=a;local b={value=1};b.self={value=1};b.self.self=b.self;rejects(a,b)
 local c=H.C.copy(a);c.value=2;rejects(a,c)
end)
test('preserves every extra missing typed key primitive value and function identity check',function()
 rejects({a=1},{a=1,extra=false});rejects({a=1,extra=false},{a=1})
 rejects({[1]='value'},{['1']='value'});rejects({value=1},{value='1'});rejects({value=false},{value=true})
 rejects({value='old'},{value='new'});rejects({nested={a=1}},{nested={a=1,extra=0}})
 local f=function()end;H.same({value=f},{value=f});rejects({value=f},{value=function()end})
 rejects({value={}},{});rejects({value={}},{value=false})
end)
test('whole actual Run snapshot retains data and combat fields in comparison',function()
 local run=H.battle({'swift_potion'},nil,'louse_pair');local snapshot=H.C.copy(run);H.same(run,snapshot)
 snapshot.data.cards.cards[1].cost=snapshot.data.cards.cards[1].cost+1;rejects(run,snapshot)
 snapshot=H.C.copy(run);snapshot.combat.player.hp=snapshot.combat.player.hp-1;rejects(run,snapshot)
end)
print('LUA_POTION_BASIC_FIVE_GRAPH_PASS '..n)
